"exacerbate":{a:[{tr:"kötüleştirmek, şiddetlendirmek",ex:"Cutting the budget would only exacerbate the problem.",exTr:"Bütçeyi kısmak sorunu yalnızca kötüleştirir."}],es:"worsen, aggravate"},
"exempt":{a:[{tr:"muaf, bağışık; muaf tutmak",ex:"Basic foodstuffs are exempt from the tax.",exTr:"Temel gıda maddeleri vergiden muaftır."}],es:"excused, free from"},
