"intricate":{a:[{tr:"karmaşık, girift, ince işlenmiş",ex:"The carpet has an intricate geometric pattern.",exTr:"Halının girift bir geometrik deseni var."}],es:"complex, elaborate"},
"mitigate":{a:[{tr:"hafifletmek, azaltmak, yumuşatmak",ex:"Planting trees can mitigate the effects of flooding.",exTr:"Ağaç dikmek sel etkilerini hafifletebilir."}],es:"alleviate, lessen"},
"negligible":{a:[{tr:"ihmal edilebilir, önemsiz",ex:"The difference in cost is negligible.",exTr:"Maliyet farkı ihmal edilebilir düzeyde."}],es:"insignificant, trivial"},
"obsolete":{a:[{tr:"demode, geçerliliğini yitirmiş, modası geçmiş",ex:"The equipment became obsolete within a decade.",exTr:"Ekipman on yıl içinde kullanılmaz hale geldi."}],es:"outdated, outmoded"},
"pervasive":{a:[{tr:"yaygın, her yere sinmiş",ex:"Corruption was pervasive at every level.",exTr:"Yolsuzluk her düzeyde yaygındı."}],es:"widespread, prevalent"},
"proponent":{a:[{tr:"savunucu, taraftar",ex:"She is a leading proponent of renewable energy.",exTr:"Yenilenebilir enerjinin önde gelen savunucularından biri."}],es:"advocate, supporter"},
"rectify":{a:[{tr:"düzeltmek, gidermek",ex:"The error was rectified within hours.",exTr:"Hata saatler içinde giderildi."}],es:"correct, put right"},
"redundant":{a:[{tr:"gereksiz, fazlalık; işten çıkarılmış",ex:"Cut any redundant words from your essay.",exTr:"Kompozisyonundaki gereksiz kelimeleri çıkar."}],es:"superfluous, unnecessary"},
"refute":{a:[{tr:"çürütmek, yalanlamak",ex:"The theory has since been refuted by new data.",exTr:"Kuram o zamandan beri yeni verilerle çürütüldü."}],es:"disprove, rebut"},
"resilient":{a:[{tr:"dirençli, çabuk toparlanan, esnek",ex:"Small businesses proved surprisingly resilient.",exTr:"Küçük işletmeler şaşırtıcı ölçüde dirençli çıktı."}],es:"tough, adaptable"},
"rigorous":{a:[{tr:"titiz, sıkı, katı",ex:"The drug underwent rigorous testing.",exTr:"İlaç sıkı testlerden geçti."}],es:"strict, thorough"},
"scrutiny":{a:[{tr:"dikkatli inceleme, mercek altına alma",ex:"The contract came under close scrutiny.",exTr:"Sözleşme yakın bir incelemeye tabi tutuldu."}],es:"examination, inspection"},
"tangible":{a:[{tr:"somut, elle tutulur",ex:"The talks produced no tangible results.",exTr:"Görüşmelerden somut bir sonuç çıkmadı."}],es:"concrete, palpable"},
"tedious":{a:[{tr:"sıkıcı, usandırıcı, bıktırıcı",ex:"Copying the figures by hand was tedious work.",exTr:"Rakamları elle kopyalamak usandırıcı bir işti."}],es:"boring, monotonous"}
